CREATE OR REPLACE FUNCTION public.validate_gym_content() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF TG_TABLE_NAME='facilities' THEN IF NEW.is_published AND NOT NEW.is_verified THEN RAISE EXCEPTION 'Verify this facility before publishing'; END IF; ELSIF TG_TABLE_NAME='membership_plans' THEN IF NEW.amount < 0 OR NEW.duration_days <= 0 THEN RAISE EXCEPTION 'Enter a valid price and duration'; END IF; IF NEW.is_published AND NEW.amount IS NULL THEN RAISE EXCEPTION 'Add a price before publishing'; END IF; END IF; RETURN NEW; END $$;